<script setup lang="ts">
import {useI18n} from 'vue-i18n'
import {settlementAmount,settlementComponent,settlementIssue} from '../supplemental'
import type {MonthBalance} from '../supplemental'
defineProps<{balances:MonthBalance[]}>()
const {locale}=useI18n(),en=()=>locale.value.startsWith('en'),x=(z:string,e:string)=>en()?e:z,money=(v:string|null|undefined)=>settlementAmount(v,en())
const components=[['employeeCpf','cpf_employee'],['employerCpf','cpf_employer'],['sdl','sdl'],['cdac','cdac']] as const
const recoveryCause=(s:string)=>({ordinary_employer_omission:x('普通雇主漏扣','Ordinary employer omission'),ordinary_non_negligent_recovery:x('普通非疏忽追回','Ordinary non-negligent recovery'),aw_statutory_reassessment:x('法定AW重新评估','Statutory AW reassessment'),already_deducted_unremitted:x('原已扣未缴','Already deducted, unremitted'),unclassified:x('未分类','Unclassified')}[s]||s)
</script>
<template><section v-for="b in balances" :key="b.month" class="wf-section"><h4>{{x('原贡献月份','Original contribution month')}} {{b.month}}</h4><p class="wf-hint">{{x('责任修订、已扣与实缴独立；负待缴为待退款／更正，不产生负工资或跨份额抵扣。','Liability revisions, deductions and remittances are independent. Negative balances require refund / correction, without negative wages or cross-share offsets.')}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{x('分项','Component')}}</th><th>{{x('目标责任','Target liability')}}</th><th>{{x('原已确认责任','Recognised liability')}}</th><th>{{x('原实际已扣','Already deducted')}}</th><th>{{x('累计实际已缴','Actually remitted')}}</th><th>{{x('责任修订','Liability revision')}}</th><th>{{x('扣款差额','Deduction difference')}}</th><th>{{x('实际待缴／待退','Remittance / refund balance')}}</th></tr></thead><tbody><tr v-for="[key,name] in components" :key="key"><th>{{settlementComponent(name,en())}}</th><td>{{money(b[key]?.target)}}</td><td>{{money(b[key]?.recognised)}}</td><td>{{money(b[key]?.deducted)}}</td><td>{{money(b[key]?.remitted)}}</td><td>{{money(b[key]?.liabilityDelta)}}</td><td>{{money(b[key]?.deductionDelta)}}</td><td>{{money(b[key]?.remittanceBalance)}} <span v-if="b[key]?.remittanceBalance?.startsWith('-')">{{x('待退款／更正','Refund / correction pending')}}</span></td></tr></tbody></table></div><p>{{x('员工CPF法定可追回金额','Legally recoverable employee CPF')}}: {{money(b.employeeCpfRecoverable)}} · {{x('不自动从后续工资收回','No automatic recovery from future wages')}}</p><dl v-if="b.recovery" class="wf-details"><dt>{{x('成因','Recovery cause')}}</dt><dd>{{recoveryCause(b.recovery.cause)}}</dd><dt>{{x('法律依据／应缴年度／截止日期','Legal basis / due year / deadline')}}</dt><dd>{{b.recovery.legalBasis||x('未知','Unknown')}} / {{b.recovery.dueYear??x('未知','Unknown')}} / {{b.recovery.deadline||x('未知','Unknown')}}</dd><dt v-if="b.recovery.cause==='aw_statutory_reassessment'||b.recovery.reconciliationId">{{x('关联原年度AW复核','Original-year AW reconciliation')}}</dt><dd v-if="b.recovery.cause==='aw_statutory_reassessment'||b.recovery.reconciliationId">{{b.recovery.reconciliationId||x('缺关联；追回资格尚未确定','No reference; recovery eligibility remains unknown')}}</dd><dt>{{x('法定上限／凭证','Maximum / evidence')}}</dt><dd>{{money(b.recovery.maximum)}} / {{b.recovery.evidenceReference||x('未知','Unknown')}}</dd></dl><p>{{x('利息状态','Interest state')}}: {{!b.interest||b.interest.state==='unknown'?x('未知；本金结清不表示全部结清','Unknown; principal settled does not mean fully settled'):b.interest.state==='assessed'?x('官方已核定','Officially assessed'):x('有依据不适用','Not applicable with evidence')}} · {{x('官方核定利息','Officially assessed interest')}}: {{money(b.interest?.assessedAmount)}} · {{b.interest?.officialReference}}</p><p v-if="b.refundRequired" role="status">{{x('退款／更正待处理；员工与雇主份额分别保留。','Refund / correction pending; employee and employer shares remain separate.')}}</p><p v-for="(code,i) in b.issues||[]" :key="i" class="wf-issue">{{settlementIssue(code,en())}} ({{code}})</p></section></template>
<style scoped>th,td{white-space:nowrap}dd{overflow-wrap:anywhere}</style>
